/**
 * Runs a query against the denormalised index. Field-scoped syntax
 * (`kind:`/`in:`/`project:`) is an `advanced_search` feature: entry points
 * pass the raw query and their default kinds straight through, and this is
 * the one place that parses it (the dialog's parser in
 * `components/domain/search/query-syntax.ts` is reused here so the two never
 * disagree on what a token means). Without the flag the whole query is free
 * text — a colon is just a character, never a reason to refuse the query —
 * and only issues are searched, whatever kinds the caller asked for.
 */
export async function search(
  actor: Actor,
  input: SearchQueryInput,
): Promise<Page<SearchHit>> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "issue:read", orgResource(input.orgId));

  const verdict = await consumeRateLimit(input.orgId, SEARCH_QUERY_BUCKET);
  if (!verdict.allowed) {
    throw new Error(
      `Search rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const org = await orgRepo.findOrgById(input.orgId);
  const advanced = isEnabled("advanced_search", {
    orgId: input.orgId,
    userId: actor.userId,
    plan: org?.plan ?? "free",
    role: actor.role,
    overrides: org?.settings.enabledFlagOverrides,
  });

  const tokens = advanced
    ? extractSearchTokens(input.q)
    : { text: input.q, kinds: [], projectId: null as ProjectId | null };

  const kinds = advanced
    ? tokens.kinds.length > 0
      ? tokens.kinds
      : input.kinds
    : DEFAULT_SEARCH_KINDS;
  const projectId = (advanced ? tokens.projectId : null) ?? input.projectId;

  const text = normaliseQuery(tokens.text);
  const page = await searchRepo.searchDocuments({
    ...input,
    q: text,
    kinds,
    projectId,
  });

  return {
    items: page.items.map((row) => ({
      kind: row.subjectKind,
      id: row.subjectId,
      title: row.content.split("\n")[0] ?? row.subjectId,
      snippet: snippetAround(row.content, text),
      href: hrefFor(row.subjectKind, row.subjectId),
    })),
    nextCursor: page.nextCursor,
    total: page.total,
  };
}

