import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { emit } from "@/lib/event-bus";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import { actorEnvelope } from "@/server/services/_support";
import * as searchService from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = searchService.registerSearchListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

describe("ad hoc verification", () => {
  it("starter plan: colon in query is literal text, not refused", async () => {
    const tenant: Tenant = await createTenant("verifystarter", "starter");
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Release 2: hotfix" }),
    );

    const hits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Release 2: hotfix",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(hits.total).toBe(1);
  });

  it("enterprise: kind:comment token narrows to comments and finds them", async () => {
    const tenant: Tenant = await createTenant("verifyent", "enterprise");
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Deploy pipeline" }),
    );
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "this test is flaky",
      parentId: null,
      mentionedUserIds: [],
    });

    const hits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "kind:comment flaky",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(hits.total).toBe(1);
    expect(hits.items[0]?.kind).toBe("comment");
  });

  it("project-scoped search returns comments on that project's issues", async () => {
    const tenant: Tenant = await createTenant("verifyproj", "enterprise");
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Scoped issue" }),
    );
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "scoped comment marker",
      parentId: null,
      mentionedUserIds: [],
    });

    const hits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "scoped comment marker",
      kinds: ["comment"],
      projectId: tenant.project.id,
      limit: 25,
      cursor: null,
    });
    expect(hits.total).toBe(1);
  });

  it("percent and underscore are literal, not SQL LIKE wildcards", async () => {
    const tenant: Tenant = await createTenant("verifylike", "enterprise");
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Totally unrelated issue" }),
    );
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Done at 100% today" }),
    );
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "please use snake case" }),
    );
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "rename to snake_case" }),
    );

    const percentHits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "100%",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(percentHits.total).toBe(1);

    const snakeHits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "snake_case",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(snakeHits.total).toBe(1);
  });

  it("growth plan (no advanced_search): command palette style request narrows to issues only", async () => {
    const tenant: Tenant = await createTenant("verifygrowth", "growth");
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Growth marker issue" }),
    );
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "Growth marker comment",
      parentId: null,
      mentionedUserIds: [],
    });

    const hits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Growth marker",
      kinds: ["issue", "comment", "project"],
      limit: 25,
      cursor: null,
    });
    expect(hits.items.every((hit) => hit.kind === "issue")).toBe(true);
  });

  it("reindexing a comment and a project via search.reindex_requested makes them searchable", async () => {
    const tenant: Tenant = await createTenant("verifyreindex", "enterprise");
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Reindex host issue" }),
    );
    const comment = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "reindex comment marker",
      parentId: null,
      mentionedUserIds: [],
    });

    // Simulate an index clean-up wiping the row, then a reindex request.
    await searchService.removeFromIndex(tenant.org.id, "comment", comment.id);
    await searchService.removeFromIndex(tenant.org.id, "project", tenant.project.id);

    await emit("search.reindex_requested", {
      ...actorEnvelope(tenant.actors.member),
      subjectKind: "comment",
      subjectId: comment.id,
    });
    await emit("search.reindex_requested", {
      ...actorEnvelope(tenant.actors.member),
      subjectKind: "project",
      subjectId: tenant.project.id,
    });

    const commentHits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "reindex comment marker",
      kinds: ["comment"],
      limit: 25,
      cursor: null,
    });
    expect(commentHits.total).toBe(1);

    const projectHits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: tenant.project.name,
      kinds: ["project"],
      limit: 25,
      cursor: null,
    });
    expect(projectHits.total).toBe(1);
  });

  it("reindexing an archived issue leaves it out of the index", async () => {
    const tenant: Tenant = await createTenant("verifyarchive", "enterprise");
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Archived reindex marker" }),
    );
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);

    await publish("search.reindex_requested", {
      orgId: tenant.org.id,
      subjectKind: "issue",
      subjectId: issue.id,
    });

    const hits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Archived reindex marker",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(hits.total).toBe(0);
  });
});
